import {
	children,
	createContext,
	createEffect,
	createMemo,
	createSignal,
	on,
	onCleanup,
	onMount,
	ParentComponent,
	Setter,
	Show,
	useContext,
} from "solid-js";

//Removing temporarily for 1.2.5. Put it back for 1.3.0 when we have legacy scroll bars are working the same way with sound.
//import { Audio } from "#core/ui/audio-base/audio-support.js";
import { InputEngineEventName, NavigateInputEvent, type InputEngineEvent } from "#core/ui/input/input-support.js";
import { NavHelp } from "#core/ui-next/components/nav-help.jsx";
import { ComponentRegistry } from "#core/ui-next/services/component-registry.js";
import { EngineInputProxyContext } from "#core/ui-next/services/input.js";

import type { Accessor, JSX } from "solid-js";

export interface ScrollAreaBaseProps {
	/** Initial scroll in percentage(0-100) */
	initialScroll?: number;
	/** The minimum thumb height as a percentage of the scroll bar track height. Default: 20  */
	minThumbHeight?: number;
	/** The default pan rate as a percentage of the scroll bar height. Default:  0.75 */
	panRate?: number;
	/** Allow the gamepad to pan the scroll area. Default: true */
	allowGamepadPan?: boolean;
	/** Allow the mouse to click and drag to pan the scroll area. Default: false */
	allowMousePan?: boolean;
	/** Use the current input proxy context as input. Default: false */
	useProxy?: boolean;
	/** Is the space for the scrollbar track reserved (true) or does content overlap it when the track is hidden (false)? Default: false  */
	reserveSpace?: boolean;
	/** (Setter) The current scroll percentage */
	setScroll?: Setter<number>;
	/** (Setter) Set to true when the scroll thumb is at the bottom of the track */
	setIsAtBottom?: Setter<boolean>;
	/** (Setter) Set to true when the scroll area track is visible */
	setIsTrackVisible?: Setter<boolean>;
	/** (Setter) Scroll area width */
	setClientWidth?: Setter<number>;
	/** (Setter) Scroll area height */
	setClientHeight?: Setter<number>;
}

export type ScrollAreaProps = ScrollAreaBaseProps & JSX.HTMLAttributes<HTMLDivElement>;

class ScrollAreaContextProvider {
	private _position: Accessor<number>;
	private _setPosition: Setter<number>;
	private _positionStart: Accessor<number>;
	private _setPositionStart: Setter<number>;

	constructor() {
		const [positionStart, setPositionStart] = createSignal(0);
		const [position, setPosition] = createSignal(0);
		this._positionStart = positionStart;
		this._setPositionStart = setPositionStart;
		this._position = position;
		this._setPosition = setPosition;
	}

	public hasScrolledFromStart() {
		return this.position() !== this.positionStart();
	}

	public get positionStart() {
		return this._positionStart;
	}

	public setPositionStart(value: number | ((prev: number) => number)) {
		return this._setPositionStart(value);
	}

	public get position() {
		return this._position;
	}

	public setPosition(value: number | ((prev: number) => number)) {
		return this._setPosition(value);
	}
}

export const ScrollAreaContext = createContext<ScrollAreaContextProvider>();

function getPercentageOffset(position: number, target: HTMLElement) {
	const trackArea = target.getBoundingClientRect();
	return ((position - trackArea.y) / trackArea.height) * 100;
}

function clampToRange(percentage: number) {
	return Math.max(0, Math.min(100, percentage));
}

// The Context Provider doesn't work if we access children(() => ...) inside it.
// We need to create a component that tracks the children after the Provider component is set.
const ChildTracker: ParentComponent<{ onChildrenMutate: () => void }> = (props) => {
	// Memoize the children so we can detect changes
	const trackedChildren = children(() => props.children);
	createEffect(
		on(
			() => trackedChildren,
			() => props.onChildrenMutate(),
		),
	);
	return <>{trackedChildren()}</>;
};

const ScrollAreaComponent: ParentComponent<ScrollAreaProps> = (props) => {
	let scrollWrapper!: HTMLDivElement;
	let content!: HTMLDivElement;
	let track!: HTMLDivElement;
	let resizeObserver: ResizeObserver | null = null;
	let lastPanTimestamp = 0;
	let isPanning = false;
	let panY = 0;
	let isStillPanningCheck = 0;
	let gamepadPanAnimationId = -1;

	const minThumbHeight = createMemo(() => props.minThumbHeight ?? 20);
	// Yay, floating point comparisons
	const scrollEndWithEpsilon = 99.99999;

	// Is drag scrolling occuring?
	const [isDragging, setIsDragging] = createSignal(false);
	// The size of the thumb in total percentage of the track (0-100)
	// eslint-disable-next-line solid/reactivity
	const [thumbHeight, setThumbHeight] = createSignal(minThumbHeight());
	// The drag offset of the thumb in total percentage of the thumb (0-100)
	const [thumbDelta, setThumbDelta] = createSignal(0);
	// The scroll position in total percentage of the scroll track (0-100)
	const [scrollPosition, setScrollPosition] = createSignal(props.initialScroll ?? 0);
	// Is the thumb visible?
	const isTrackVisible = createMemo(() => thumbHeight() <= scrollEndWithEpsilon);

	const panRate = createMemo(() => props.panRate ?? 0.75);
	const allowGamepadPan = createMemo(() => props.allowGamepadPan ?? true);

	const proxy = useContext(EngineInputProxyContext);
	const scrollContext = new ScrollAreaContextProvider();
	scrollContext.setPositionStart(props.initialScroll ?? 0);

	let pendingFocus: HTMLElement | null = null;

	createEffect(() => {
		const position = scrollPosition();
		const isBottom = position >= scrollEndWithEpsilon;
		const newScrollTop = Math.floor(
			(position / 100) * Math.max(1, scrollWrapper.scrollHeight - scrollWrapper.clientHeight),
		);

		if (scrollWrapper.scrollTop != newScrollTop) {
			scrollWrapper.scrollTop = newScrollTop;
		}

		props.setIsAtBottom?.(isBottom);
	});

	createEffect(() => props.setIsTrackVisible?.(isTrackVisible()));

	const thumbScrollPosition = createMemo(() => {
		return (scrollPosition() / thumbHeight()) * (100 - thumbHeight());
	});

	const scaleByThumbSize = (percentage: number, thumbOffsetPercent: number) => {
		return (100 * percentage - thumbHeight() * thumbOffsetPercent) / (100 - thumbHeight());
	};

	const scrollToPercent = (position: number) => {
		// If the position has changed, send audio event.
		const clampedPosition = clampToRange(position);
		if (clampedPosition != scrollPosition()) {
			//removing temporarily for 1.2.5. Put it back for 1.3.0 when we have legacy scroll bars doing this too.
			//Audio.playSound("data-audio-slider-changed");
		}

		setScrollPosition(clampedPosition);
		scrollContext.setPosition(clampedPosition);
		props.setScroll?.(clampedPosition);
	};

	const scrollToTrackPosition = (positionInPixels: number, thumbOffsetPercent = 50) => {
		const positionPercent = getPercentageOffset(positionInPixels, track);
		scrollToPercent(scaleByThumbSize(positionPercent, thumbOffsetPercent));
	};

	const scrollByPercent = (percentage: number) => {
		scrollToPercent(scrollPosition() + percentage);
	};

	const scrollByPixels = (pixels: number) => {
		const height = Math.max(1, scrollWrapper.scrollHeight - scrollWrapper.clientHeight);
		scrollByPercent((pixels / height) * 100);
	};

	const scrollToElement = (element: HTMLElement | null) => {
		if (!element) {
			return;
		}

		const areaRect = scrollWrapper.getBoundingClientRect();
		const targetRect = element.getBoundingClientRect();
		let distToMove = 0;

		if (targetRect.top <= areaRect.top && targetRect.bottom != areaRect.bottom) {
			distToMove = targetRect.top - areaRect.top;
		} else if (targetRect.bottom > areaRect.bottom) {
			distToMove = targetRect.bottom - areaRect.bottom;
		}

		if (distToMove != 0) {
			scrollByPixels(distToMove);
		}
	};

	const updateScrollThumbPosition = () => {
		const positionPercentage =
			(scrollWrapper.scrollTop / Math.max(1, scrollWrapper.scrollHeight - scrollWrapper.clientHeight)) * 100;
		scrollToPercent(positionPercentage);
	};

	const dragStart = () => {
		if (!isDragging()) {
			setIsDragging(true);
		}
	};

	const dragEnd = () => {
		if (isDragging()) {
			setIsDragging(false);
		}
	};

	const handleTrackClick = (event: MouseEvent) => {
		scrollToTrackPosition(event.clientY);
		event.stopPropagation();
	};

	const handleThumbMouseMove = (event: MouseEvent) => {
		scrollToTrackPosition(event.clientY, thumbDelta());
		event.stopPropagation();
	};

	const handleThumbMouseUp = (event: MouseEvent) => {
		dragEnd();

		window.removeEventListener("mousemove", handleThumbMouseMove);
		window.removeEventListener("mouseup", handleThumbMouseUp, true);
		event.stopPropagation();
	};

	const handleThumbMouseDown = (event: MouseEvent) => {
		dragStart();
		setThumbDelta(getPercentageOffset(event.clientY, event.target as HTMLElement));

		window.addEventListener("mousemove", handleThumbMouseMove);
		window.addEventListener("mouseup", handleThumbMouseUp, true);
		event.stopPropagation();
	};

	const handleThumbEngineInput = (inputEvent: InputEngineEvent) => {
		let handled = false;

		if (inputEvent.detail.name == "touch-pan" && inputEvent.detail.status == InputActionStatuses.START) {
			dragStart();
			handled = true;
		}

		if (handled) {
			inputEvent.preventDefault();
			inputEvent.stopPropagation();
		}
	};

	const handleFocus = (event: FocusEvent) => {
		// Focus tree walking or slot navigation misses can cause multiple child focus events.
		// Scrolling doesn't change bounds until the next layout pass, causing subsequent scrolls to use the wrong bounds.
		// We can solve this by only scrolling to the last focused element.
		if (!pendingFocus) {
			requestAnimationFrame(() => {
				if (pendingFocus) {
					scrollToElement(pendingFocus as HTMLElement | null);
					pendingFocus = null;
				}
			});
		}

		pendingFocus = event.target as HTMLElement | null;
	};

	const handleThumbResize = () => {
		// eslint-disable-next-line solid/reactivity
		waitForLayout(() => {
			const clientHeight = scrollWrapper.clientHeight;
			const calcThumbHeight = (Math.max(1, clientHeight) / Math.max(1, scrollWrapper.scrollHeight)) * 100;
			setThumbHeight(Math.max(calcThumbHeight, minThumbHeight()));
			updateScrollThumbPosition();
			props.setClientHeight?.(clientHeight);
			props.setClientWidth?.(content.clientWidth);
		});
	};

	const handleWindowEngineInput = (inputEvent: InputEngineEvent) => {
		if (inputEvent.detail.name == "touch-complete") {
			dragEnd();
			inputEvent.preventDefault();
			inputEvent.stopPropagation();
		}
	};

	const handleTouchOrMousePan = (inputEvent: InputEngineEvent) => {
		const y = inputEvent.detail.y;
		let handled = false;

		switch (inputEvent.detail.status) {
			case InputActionStatuses.START:
				panY = y;
				handled = true;
				break;
			case InputActionStatuses.DRAG:
				if (isDragging()) {
					scrollToTrackPosition(y, thumbDelta());
				} else {
					scrollByPixels(panY - y);
					panY = y;
				}
				handled = true;
				break;
		}

		if (handled) {
			inputEvent.preventDefault();
			inputEvent.stopPropagation();
		}
	};

	const handleGamepadPanUpdate = (timestamp: DOMHighResTimeStamp) => {
		if (isStillPanningCheck >= 10) {
			// We are still panning if the active element (focus) is still within the scrollable (or we are using a proxy)
			isPanning = props.useProxy || (scrollWrapper.contains(document.activeElement) ?? false);
			isStillPanningCheck = 0;
		}

		if (isPanning) {
			isStillPanningCheck += 1;
			gamepadPanAnimationId = requestAnimationFrame(handleGamepadPanUpdate);
			const diff = timestamp - lastPanTimestamp;
			lastPanTimestamp = timestamp;
			scrollByPixels(panY * diff * panRate());
		} else {
			isStillPanningCheck = 0;
			panY = 0;
			gamepadPanAnimationId = -1;
		}
	};

	const handleGamepadPan = (inputEvent: InputEngineEvent | NavigateInputEvent) => {
		switch (inputEvent.detail.status) {
			case InputActionStatuses.START:
				lastPanTimestamp = performance.now();
				isPanning = true;
				panY = -inputEvent.detail.y;
				if (gamepadPanAnimationId == -1) {
					gamepadPanAnimationId = requestAnimationFrame(handleGamepadPanUpdate);
				}
				break;

			case InputActionStatuses.UPDATE:
				panY = -inputEvent.detail.y;
				break;

			case InputActionStatuses.FINISH:
				isPanning = false;
				panY = 0;
				isStillPanningCheck = 0;
				break;
		}
	};

	const handleEngineInput = (inputEvent: InputEngineEvent) => {
		if (inputEvent.detail.name == "scroll-pan" && allowGamepadPan()) {
			handleGamepadPan(inputEvent);
			inputEvent.preventDefault();
			inputEvent.stopPropagation();
		}

		if (
			(inputEvent.detail.name == "touch-pan" && inputEvent.currentTarget == props.ref) ||
			(props.allowMousePan && inputEvent.detail.name == "mousebutton-left")
		) {
			handleTouchOrMousePan(inputEvent);
		}

		if (inputEvent.detail.status != InputActionStatuses.FINISH) {
			return;
		}
	};

	createEffect(() => {
		if (props.useProxy) {
			proxy?.registerHandler(handleEngineInput);
		} else {
			proxy?.unregisterHandler(handleEngineInput);
		}
	});

	onMount(() => {
		resizeObserver = new ResizeObserver(handleThumbResize);
		resizeObserver.observe(content);

		// NOTE: Gameface doesn't handle listener object notation so we have to bind capture events manually
		scrollWrapper.addEventListener("focus", handleFocus, true);

		window.addEventListener(InputEngineEventName, handleWindowEngineInput);

		handleThumbResize();
	});

	onCleanup(() => {
		if (props.useProxy && proxy) {
			proxy.unregisterHandler(handleEngineInput);
		}

		if (resizeObserver) {
			resizeObserver.unobserve(content);
			resizeObserver.disconnect();
			resizeObserver = null;
		}

		scrollWrapper.removeEventListener("focus", handleFocus, true);

		window.removeEventListener(InputEngineEventName, handleWindowEngineInput);
	});

	return (
		<div
			{...props}
			ref={props.ref}
			class={`flex flex-row overflow-hidden ${props.class ?? ""}`}
			on:engine-input={handleEngineInput}
			data-name="ScrollArea"
		>
			<ScrollAreaContext.Provider value={scrollContext}>
				<div
					ref={(ref) => {
						scrollWrapper = ref;
					}}
					class="flex flex-col flex-auto overflow-auto w-full"
					on:scroll={updateScrollThumbPosition}
				>
					<div
						ref={(ref) => {
							content = ref;
						}}
					>
						<ChildTracker onChildrenMutate={handleThumbResize}>{props.children}</ChildTracker>
					</div>
				</div>
				<div
					ref={(ref) => {
						track = ref;
					}}
					class="scroll-area_track mx-2 w-4 relative"
					on:mousedown={handleTrackClick}
					classList={{
						hidden: !isTrackVisible() && !props.reserveSpace,
						"opacity-0": !isTrackVisible() && props.reserveSpace,
					}}
				>
					<div
						class="scroll-area_thumb scroll-area_thumb-bg relative top-0 h-10 w-4"
						style={{
							top: "0px",
							transform: `translateY(${thumbScrollPosition()}%)`,
							height: `${thumbHeight()}%`,
						}}
						on:mousedown={handleThumbMouseDown}
						on:engine-input={handleThumbEngineInput}
					>
						<div class={`scroll-area_thumb-highlight absolute inset-0`} />
						<div class={`scroll-area_thumb-active absolute inset-0`} />
						<Show when={allowGamepadPan()}>
							<NavHelp
								actionName="inline-scroll-pan"
								class="absolute top-1\/2 -right-2 -translate-y-1\/2"
							/>
						</Show>
					</div>
				</div>
			</ScrollAreaContext.Provider>
		</div>
	);
};

/**
 * A vertically scrollable area.
 * ```tsx
 * <ScrollArea>
 * ... Long list of stuff ...
 * </ScrollArea>
 * ```
 * Default implementation: {@link ScrollAreaComponent}
 * @param {ScrollAreaProps} props See {@link ScrollAreaProps} for a full list of properties
 */
export const ScrollArea = ComponentRegistry.register({
	name: "ScrollArea",
	createInstance: ScrollAreaComponent,
	images: [
		"blp:base_scrollbar-track.png",
		"blp:base_scrollbar-handle.png",
		"blp:base_scrollbar-handle-focus.png",
		"blp:base_scrollbar-handle-focus.png",
	],
});
